def max_subarray(nums: list[int]) -> int:
    """Return the maximum contiguous subarray sum using Kadane's algorithm."""
    best = current = nums[0]
    for n in nums[1:]:
        current = max(n, current + n)
        best = max(best, current)
    return best


if __name__ == "__main__":
    examples = [
        [-2, 1, -3, 4, -1, 2, 1, -5, 4],  # answer: 6  (subarray [4,-1,2,1])
        [1],                                 # answer: 1
        [-3, -2, -1],                        # answer: -1
        [5, 4, -1, 7, 8],                    # answer: 23
    ]
    for arr in examples:
        print(f"{arr!s:40s} -> {max_subarray(arr)}")
